#include <iostream>
#include <vector>
using namespace std;

template <typename T>
class Pouch {
public:
    void put(T x) { goods.push_back(x); }
    int count() { return goods.size(); }
    T at(int i) { return goods[i]; }
private:
    vector<T> goods;
};

int main() {
    Pouch<int> p;
    p.put(4);
    p.put(6);
    cout << p.count() << endl;
    cout << p.at(1) << endl;
    Pouch<double> q;
    q.put(1.5);
    cout << q.count() << endl;
    return 0;
}

